import{_ as t,o as e,c as i,a2 as l}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"GitHub Webhook 自動部署教學","description":"","frontmatter":{},"headers":[],"relativePath":"github.md","filePath":"github.md","lastUpdated":null}'),r={name:"github.md"};function a(n,o,s,d,c,g){return e(),i("div",null,[...o[0]||(o[0]=[l('<h1 id="github-webhook-自動部署教學" tabindex="-1">GitHub Webhook 自動部署教學 <a class="header-anchor" href="#github-webhook-自動部署教學" aria-label="Permalink to &quot;GitHub Webhook 自動部署教學&quot;">​</a></h1><p>綁定 Webhook 後，當您向 GitHub 提交代碼 (<code>git push</code>) 時，Craft-Core Hosting 會自動執行以下流程：</p><ol><li>自動校驗簽名</li><li>執行代碼拉取 (<code>git pull</code>)</li><li>自動執行套件安裝 (<code>npm install</code> / <code>pip install</code>)</li><li>重啟 Docker 容器</li></ol><hr><h2 id="設定指南" tabindex="-1">設定指南 <a class="header-anchor" href="#設定指南" aria-label="Permalink to &quot;設定指南&quot;">​</a></h2><ol><li><p><strong>複製 Webhook Payload URL</strong></p><ul><li>在專案頁面的「設定 (Settings)」分頁中複製該機器的專屬 Payload URL 與 Secret。</li></ul></li><li><p><strong>至 GitHub 新增 Webhook</strong></p><ul><li>進入 GitHub 儲存庫 ➔ <strong>Settings</strong> ➔ <strong>Webhooks</strong> ➔ <strong>Add webhook</strong>。</li><li><strong>Payload URL</strong>: 貼上複製的專屬 URL。</li><li><strong>Content type</strong>: 選擇 <code>application/json</code>。</li><li><strong>Secret</strong>: 貼上專案的 Webhook Secret 密鑰。</li><li>點擊 <strong>Add webhook</strong> 保存。</li></ul></li><li><p><strong>提交代碼驗證</strong></p><ul><li>在本地執行 <code>git push origin main</code> 即可自動觸發持續部署。</li></ul></li></ol>',6)])])}const p=t(r,[["render",a]]);export{u as __pageData,p as default};
